// Normalize LinkedIn (Apify) item + description diagnostics fields
const j = $json;

const descText = String(j.descriptionText || '');
const descHtml = String(j.descriptionHtml || '');
const descLegacy = String(j.description || '');
const rawDesc = descText || descLegacy || descHtml.replace(/<[^>]+>/g, ' ');

const KEYWORDS = ["AI Product Analyst", "AI Product Manager", "Technical Product Analyst", "Data Product Analyst", "AI Product Specialist", "AI Solutions Analyst", "AI Solutions Specialist", "AI Solutions Consultant", "AI Implementation Specialist", "AI Implementation Analyst", "AI Automation Analyst", "AI Automation Specialist", "AI Business Transformation", "AI Transformation Analyst", "AI Business Analyst", "AI Workflow Automation", "AI Product Operations", "AI Process Automation Analyst", "AI Strategy Analyst", "AI Product Business Analyst", "Business Analyst", "Business Insights", "Business Performance", "Business Strategy Analyst", "Strategy Analyst", "Strategy Analytics", "Customer Insights", "Customer Analytics", "Product Analyst", "Product Analytics", "Growth Analytics", "Business Operations Analyst", "Process Improvement Analyst", "Process Optimization Analyst", "Operational Excellence Analyst", "Global Markets", "Capital Markets Analyst", "Capital Markets Risk", "Market Risk Analyst", "Risk Strategy Analyst", "Credit Risk Analyst", "Credit Strategy Analyst", "Counterparty Credit Risk", "Fraud Risk Analyst", "Fraud Strategy Analyst", "Payment Risk Analyst", "Transaction Risk Analyst", "Treasury Analyst", "ALM Analyst", "FX Risk Analyst", "Rates Analyst", "Fixed Income Analyst", "Interest Rate Risk Analyst", "Risk Analyst"];

function inferSourceKeyword(title) {
  const t = String(title || '');
  for (const kw of KEYWORDS) {
    const re = new RegExp(kw.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
    if (re.test(t)) return kw;
  }
  return 'unknown';
}

return {
  source: 'linkedin',
  id: j.id || '',
  title: (j.title || '').trim(),
  company: (j.companyName || '').trim(),
  location: (j.location || '').trim(),
  url: (j.link || j.applyUrl || '').trim(),
  apply_url: j.applyUrl || '',
  posted_at: j.postedAt || new Date().toISOString(),
  seniority_level: j.seniorityLevel || '',
  employment_type: j.employmentType || '',
  job_function: j.jobFunction || '',
  industries: j.industries || '',
  salary: j.salary || '',
  raw_description: rawDesc,
  source_keyword_inferred: inferSourceKeyword(j.title),
  description_diagnostics: {
    has_descriptionText: descText.length > 0,
    has_descriptionHtml: descHtml.length > 0,
    has_description_legacy: descLegacy.length > 0,
    descriptionText_length: descText.length,
    descriptionHtml_length: descHtml.length,
    description_legacy_length: descLegacy.length,
    raw_description_length: rawDesc.length,
    apify_field_used: descText ? 'descriptionText' : (descLegacy ? 'description' : (descHtml ? 'descriptionHtml' : 'none')),
    likely_snippet_only: rawDesc.length > 0 && rawDesc.length < 400,
    likely_full_jd: rawDesc.length >= 800,
  },
  company_website: j.companyWebsite || '',
  company_linkedin: j.companyLinkedinUrl || '',
  company_slogan: j.companySlogan || '',
  company_description: j.companyDescription || '',
  company_employees: j.companyEmployeesCount ?? null,
  company_logo: j.companyLogo || '',
  company_address: j.companyAddress
    ? [j.companyAddress.streetAddress, j.companyAddress.addressLocality, j.companyAddress.addressRegion, j.companyAddress.postalCode, j.companyAddress.addressCountry].filter(Boolean).join(', ')
    : '',
  text_for_matching: [j.title, j.companyName, j.location, j.descriptionText, j.companyDescription].filter(Boolean).join(' — ').replace(/\s+/g, ' ').slice(0, 20000),
};

// Dedupe + job title/eligibility filter, with removed_reason diagnostics

function hashKey(title, company, url) {
  const s = (title || '') + '|' + (company || '') + '|' + (url || '');
  let h = 5381;
  for (let i = 0; i < s.length; i++) h = ((h << 5) + h) + s.charCodeAt(i);
  return (h >>> 0).toString(16);
}

// Role-level technical exclusions: the candidate is business/AI-application oriented, NOT a production software/ML engineer.
// Evaluate against the advertised job title only; JD references to engineers as collaborators are allowed.
const CORE_CODING_TITLE_RE = [
  /\b(?:data|applied|research|machine learning|ml|ai|artificial intelligence)\s+scientist\b/i,
  /\b(?:research scientist|research engineer|researcher|deep learning researcher)\b/i,
  /\b(?:ai|artificial intelligence|generative ai|genai|llm|machine learning|ml|deep learning)\s+(?:engineer|developer|architect)\b/i,
  /\b(?:software|backend|back-end|frontend|front-end|full[- ]?stack|platform|data|cloud|devops|mlops)\s+(?:engineer|developer|architect)\b/i,
  /\b(?:solutions?|solution|technical)\s+(?:engineer|architect)\b/i,
  /\b(?:software|machine learning|ml)\s+development\s+engineer\b/i,
];
function isCoreCodingTitle(title) {
  return CORE_CODING_TITLE_RE.some(re => re.test(String(title || '')));
}

const ANALYST_SAFE = [/financial analyst/i,/fp&a analyst/i,/finance analyst/i,/strategic finance analyst/i,/profitability analyst/i,/process improvement analyst/i,/process optimization analyst/i,/business process analyst/i,/business process improvement analyst/i,/operational excellence analyst/i,/continuous improvement analyst/i,/operations analyst/i,/business operations analyst/i,/performance improvement analyst/i,/process analyst/i];

const ACCOUNTING_TITLE_BAN = [
  /\bfinancial accountant\b/i,/\bsenior financial accountant\b/i,/\baccountant\b/i,/\bsenior accountant\b/i,
  /\baccounting clerk\b/i,/\baccounting manager\b/i,/\bbookkeeper\b/i,/\bcontroller\b/i,/\bpayroll\b/i,
  /\baccounts payable\b/i,/\baccounts receivable\b/i,/\btax accountant\b/i,/\baudit associate\b/i,
];

const TITLE_BAN_RULES = [
  { re: /\bco[- ]?op\b/i, reason: 'co-op or student program' },
  { re: /\bstudent\b/i, reason: 'co-op or student program' },
  { re: /\bsummer student\b/i, reason: 'co-op or student program' },
  { re: /\bvolunteer\b/i, reason: 'volunteer' },
  { re: /\bresearch associate\b/i, reason: 'research non-finance' },
  { re: /\bresearch assistant\b/i, reason: 'research non-finance' },
  { re: /\badministrative assistant\b/i, reason: 'sales or admin' },
  { re: /\bcustomer service\b/i, reason: 'sales or admin' },
  { re: /\bcall center\b/i, reason: 'sales or admin' },
  { re: /\brecruiter\b/i, reason: 'sales or admin' },
  { re: /\btalent acquisition\b/i, reason: 'sales or admin' },
  { re: /\baccount executive\b/i, reason: 'sales or admin' },
  { re: /\bbusiness development\b/i, reason: 'sales or admin' },
  { re: /\bdirector\b/i, reason: 'manager-heavy title' },
  { re: /\b(vp|vice president|svp|evp)\b/i, reason: 'manager-heavy title' },
  { re: /\breception(ist)?\b/i, reason: 'sales or admin' },
  { re: /\boffice assistant\b/i, reason: 'sales or admin' },
];

const DESC_BAN_RULES = [
  { re: /\bsoftware engineer\b/i, reason: 'developer or engineering title' },
  { re: /\bdata engineer\b/i, reason: 'developer or engineering title' },
  { re: /\bdevops\b/i, reason: 'developer or engineering title' },
  { re: /\bcloud infrastructure\b/i, reason: 'developer or engineering title' },
  { re: /\bbackend engineer\b/i, reason: 'developer or engineering title' },
  { re: /\bfrontend engineer\b/i, reason: 'developer or engineering title' },
  { re: /\bfull[- ]?stack\b/i, reason: 'developer or engineering title' },
  { re: /\betl pipeline\b/i, reason: 'developer or engineering title' },
  { re: /\bdatabase administrator\b/i, reason: 'developer or engineering title' },
  { re: /\bdata architect\b/i, reason: 'developer or engineering title' },
  { re: /\bmlops\b/i, reason: 'developer or engineering title' },
  { re: /\bplatform engineer\b/i, reason: 'developer or engineering title' },
  { re: /\baml investigator\b/i, reason: 'pure compliance or case review' },
  { re: /\bkyc case review\b/i, reason: 'pure compliance or case review' },
  { re: /\btransaction case review\b/i, reason: 'pure compliance or case review' },
  { re: /\bcompliance testing\b/i, reason: 'pure compliance or case review' },
  { re: /\bsanctions screening\b/i, reason: 'pure compliance or case review' },
  // Product Managers are evaluated by actual product duties and seniority, not blanket-banned.
];

const PRIORITY_1 = [
  // AI Solutions & Product
  /ai product/i, /technical product analyst/i, /data product analyst/i, /ai solutions?/i,
  /ai implementation/i, /ai automation/i, /ai business transformation/i,
  /ai transformation/i, /ai business analyst/i, /ai workflow automation/i, /ai strategy/i, /ai process automation/i,
  // Business & Strategy Analytics
  /business analyst/i, /business insights/i, /business performance/i, /business strategy/i,
  /strategy analyst/i, /strategy analytics/i, /customer insights/i, /customer analytics/i,
  /product analyst/i, /product analytics/i, /growth analytics/i, /business operations analyst/i,
  /process improvement analyst/i, /process optimization analyst/i, /operational excellence analyst/i,
  // Global Markets & Risk
  /global markets/i, /capital markets/i, /market risk/i, /risk strategy/i,
  /credit risk/i, /credit strategy/i, /counterparty credit risk/i,
  /fraud risk/i, /fraud strategy/i, /payment risk/i, /transaction risk/i,
  /treasury analyst/i, /alm analyst/i, /fx risk/i, /rates analyst/i,
  /fixed income analyst/i, /interest rate risk/i, /risk analyst/i,
];
const PRIORITY_2 = [
  // Adjacent titles are assessed against the three target families by their duties.
  /data analyst/i, /growth analyst/i, /operations analyst/i, /performance analyst/i,
  /revenue analyst/i, /pricing analyst/i, /process analyst/i, /portfolio analyst/i,
  /financial analyst/i, /fp&a analyst/i,
];

const PURE_OPS_TITLE_PATTERNS = [
  /\bpure operations coordinator\b/i,/\boperations coordinator\b/i,/\badministrative operations\b/i,
  /\bcustomer service operations\b/i,/\bwarehouse operations\b/i,/\bstore operations\b/i,
  /\bdispatch coordinator\b/i,/\bscheduling coordinator\b/i,/\blogistics coordinator\b/i,
  /\boperations specialist\b/i,/\boperations associate\b/i,/\boperations clerk\b/i,
];

const ANALYTICS_IMPROVEMENT_SIGNALS = [
  /\banalytics\b/i,/\bkpi\b/i,/\breporting\b/i,/\broot cause\b/i,/\bprocess improvement\b/i,
  /\befficiency\b/i,/\bautomation\b/i,/\bcost reduction\b/i,/\brisk\b/i,/\bdecision support\b/i,
  /\bdata analysis\b/i,/\bdashboard\b/i,/\bbottleneck\b/i,/\bcontinuous improvement\b/i,
  /\boperational excellence\b/i,/\bworkflow analysis\b/i,/\bprocess optimization\b/i,
];

function isPureOpsExecutionWithoutAnalytics(title, hay) {
  const t = String(title || '');
  const h = String(hay || '');
  const hasAnalytics = ANALYTICS_IMPROVEMENT_SIGNALS.some(re => re.test(h));
  if (hasAnalytics) return false;
  if (PURE_OPS_TITLE_PATTERNS.some(re => re.test(t))) return true;
  if (/\boperations\b/i.test(t) && !/\banalyst\b/i.test(t) && /\b(coordinator|specialist|associate|clerk|assistant|representative)\b/i.test(t)) return true;
  if (/\b(sop documentation|process documentation|documentation only|maintain sop|sop maintenance)\b/i.test(h) && !hasAnalytics) return true;
  if (/\bprocess documentation\b/i.test(t) && !/\banalyst\b/i.test(t) && !hasAnalytics) return true;
  return false;
}


function requiresCurrentEnrollment(hay) {
  if (/\bco[- ]?op enrollment\b/i.test(hay)) return true;
  if (/\bcurrent(ly)? enrolled\b/i.test(hay) && /\b(undergrad|student|co[- ]?op)\b/i.test(hay)) return true;
  if (/\b(must be|currently)\s+(a\s+)?student\b/i.test(hay)) return true;
  if (/\b(current student|actively enrolled|enrolled in (a )?(university|college|degree) program)\b/i.test(hay)) return true;
  if (/\b(campus program|graduate program|rotational program)\b/i.test(hay) && /\b(current(ly)? enrolled|must be enrolled|active student|co[- ]?op enrollment)\b/i.test(hay)) return true;
  return false;
}

function getRemovalReason(title, url, hay) {
  if (!String(title || '').trim() || !String(url || '').trim()) return 'missing title or link';
  if (isCoreCodingTitle(title)) return 'core programming / AI research role';
  if (!ANALYST_SAFE.some(re => re.test(title))) {
    if (ACCOUNTING_TITLE_BAN.some(re => re.test(title))) return 'accounting-heavy title';
    if (/\bsales\b/i.test(title) && !/analyst/i.test(title)) return 'sales or admin';
  }
  if (isPureOpsExecutionWithoutAnalytics(title, hay)) return 'pure operations execution without analytics';
  for (const rule of TITLE_BAN_RULES) if (rule.re.test(title)) return rule.reason;
  if (requiresCurrentEnrollment(hay)) return 'co-op or student program';
  // Engineering/compliance exclusions refer to the advertised JOB TITLE only. A JD that mentions cross-functional software engineers is not itself a software-engineer job.
  for (const rule of DESC_BAN_RULES) if (rule.re.test(title)) return rule.reason;
  return null;
}

function bucket(title) {
  if (PRIORITY_1.some(re => re.test(title))) return 1;
  if (PRIORITY_2.some(re => re.test(title))) return 2;
  return 3;
}

const input = $input.all();
const seen = new Set();
const buckets = { 1: [], 2: [], 3: [] };
const removed = [];
const removedByReason = {};

for (let i = 0; i < input.length; i++) {
  const src = input[i];
  const j = { ...(src.json || {}) };
  const title = (j.title || '').trim();
  const url = (j.url || j.apply_url || '').trim();
  const hay = (title + ' ' + (j.raw_description || '')).toLowerCase();

  const reason = getRemovalReason(title, url, hay);
  if (reason) {
    removed.push({ title, company: j.company || '', location: j.location || '', url, removed_reason: reason, source_keyword: j.source_keyword_inferred || 'unknown' });
    removedByReason[reason] = (removedByReason[reason] || 0) + 1;
    continue;
  }

  const k = hashKey(title.toLowerCase(), (j.company || '').toLowerCase(), url.toLowerCase());
  if (seen.has(k)) {
    removed.push({ title, company: j.company || '', location: j.location || '', url, removed_reason: 'duplicate', source_keyword: j.source_keyword_inferred || 'unknown' });
    removedByReason.duplicate = (removedByReason.duplicate || 0) + 1;
    continue;
  }
  seen.add(k);
  j.hash = k;
  buckets[bucket(title)].push({ json: j, pairedItem: { item: i } });
}

const keptFlat = [...buckets[1], ...buckets[2], ...buckets[3]];
const keptSummary = keptFlat.slice(0, 50).map(it => ({
  title: it.json.title,
  company: it.json.company,
  location: it.json.location,
  source_keyword: it.json.source_keyword_inferred || 'unknown',
  description_length: it.json.description_diagnostics?.raw_description_length ?? (it.json.raw_description || '').length,
}));

const staticData = $getWorkflowStaticData('global');
staticData.diagnostics = staticData.diagnostics || {};
staticData.diagnostics.filter = {
  total_raw_input: input.length,
  total_after_filter: keptFlat.length,
  total_removed: removed.length,
  removed_by_reason: removedByReason,
  removed_jobs_top50: removed.slice(0, 50),
  kept_jobs_top50: keptSummary,
};

return keptFlat;

