// Prepare compact prompt input for AI scoring agent

function getCvText() {
  try {
    const local = $('MapLocalProfile').first()?.json?.cv_text;
    if (local && String(local).trim().length > 0) return String(local).trim();
  } catch (e) {}
  return '';
}

const cv_text = getCvText();
const job = $json;

const maxDesc = 5000;
const cleanDesc = (job.raw_description || '')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, maxDesc);

const jobTextBlock = [
  `Job title: ${job.title || ''}`,
  `Company: ${job.company || ''}`,
  job.location ? `Location: ${job.location}` : '',
  job.seniority_level ? `Seniority: ${job.seniority_level}` : '',
  job.employment_type ? `Employment type: ${job.employment_type}` : '',
  job.industries ? `Industry: ${job.industries}` : '',
  job.job_function ? `Function: ${job.job_function}` : '',
  '',
  'Job Description:',
  cleanDesc,
].filter(Boolean).join('\n');

return {
  job_text: jobTextBlock,
  cv_text,
  job_meta: {
    title: job.title || '',
    company: job.company || '',
    location: job.location || '',
    url: job.url || job.apply_url || '',
    posted_at: job.posted_at || '',
    seniority_level: job.seniority_level || '',
    employment_type: job.employment_type || '',
    industries: job.industries || '',
    job_function: job.job_function || '',
    source_keyword: job.source_keyword_inferred || '',
  },
  raw_description: job.raw_description || '',
};

// Normalize LLM JSON (structured parser or raw text)

let data;

if ($json.output && typeof $json.output === 'object' && !Array.isArray($json.output)) {
  data = { ...$json.output };
} else {
  let raw;
  if (typeof $json.output === 'string') {
    raw = $json.output;
  } else if ($json.choices?.[0]?.message?.content) {
    raw = $json.choices[0].message.content;
  } else {
    raw = JSON.stringify($json);
  }

  raw = raw.trim().replace(/^```json/i, '').replace(/```$/, '').trim();

  try {
    data = JSON.parse(raw);
    if (data.output && typeof data.output === 'object') data = { ...data.output };
  } catch (e) {
    const m = raw.match(/\{[\s\S]*\}/);
    if (m) {
      try {
        data = JSON.parse(m[0]);
        if (data.output && typeof data.output === 'object') data = { ...data.output };
      } catch (e2) {
        data = { parse_error: e2.message, raw };
      }
    } else {
      data = { parse_error: e.message, raw };
    }
  }
}

if (data.score && data.overall_score == null && data.score.overall != null) {
  data.overall_score = data.score.overall;
}

// Flatten bilingual + scoring fields to top level for merge/email nodes
return {
  ...data,
  output: { ...data },
};

// Output count: Top 5 default, all score>=80 when >5 qualify, plus protected matches (max 8 total).
const MAX_OUTPUT = 8;
const itemsIn = $input.all();

function getTitle(j) {
  return String(j.job_meta?.title || j.title || j.job_title || j.output?.title || j.output?.job_title || "");
}

function getCompany(j) {
  return String(j.job_meta?.company || j.company || j.companyName || j.output?.company || j.output?.companyName || "");
}

function getLocation(j) {
  return String(j.job_meta?.location || j.location || j.output?.location || "");
}

function getScore(j) {
  const value = j.overall_score ?? j.output?.overall_score ?? j.score ?? j.output?.score ?? 0;
  const num = Number(value);
  return Number.isFinite(num) ? num : 0;
}

function getDecision(j) {
  return String(j.application_decision || j.output?.application_decision || "").trim();
}

function getSeniority(j) {
  return String(j.seniority_fit || j.output?.seniority_fit || "").trim();
}

function getTargetFamily(j) {
  return String(j.target_family || j.output?.target_family || "").trim();
}

function getKeywordsText(j) {
  const kws = j.top_keywords || j.output?.top_keywords || j.keywords || j.output?.keywords || [];
  const list = Array.isArray(kws) ? kws : [];
  return list.join(" ");
}

function jobKey(j) {
  const url = String(j.job_meta?.url || j.url || j.apply_url || "").trim();
  if (url) return url;
  return getTitle(j) + "|" + getCompany(j);
}

function isToronto(j) {
  return getLocation(j).toLowerCase().includes("toronto");
}

// Role-level technical exclusions: the candidate is business/AI-application oriented, NOT a production software/ML engineer.
// Evaluate against the advertised job title only; JD references to engineers as collaborators are allowed.
const CORE_CODING_TITLE_RE = [
  /\b(?:data|applied|research|machine learning|ml|ai|artificial intelligence)\s+scientist\b/i,
  /\b(?:research scientist|research engineer|researcher|deep learning researcher)\b/i,
  /\b(?:ai|artificial intelligence|generative ai|genai|llm|machine learning|ml|deep learning)\s+(?:engineer|developer|architect)\b/i,
  /\b(?:software|backend|back-end|frontend|front-end|full[- ]?stack|platform|data|cloud|devops|mlops)\s+(?:engineer|developer|architect)\b/i,
  /\b(?:solutions?|solution|technical)\s+(?:engineer|architect)\b/i,
  /\b(?:software|machine learning|ml)\s+development\s+engineer\b/i,
];
function isCoreCodingTitle(title) {
  return CORE_CODING_TITLE_RE.some(re => re.test(String(title || '')));
}

function isBlockedTitle(title) {
  const t = String(title || "").toLowerCase();
  if (isCoreCodingTitle(t)) return true;
  // "Product Manager" is often an individual-contributor job; still screen senior-level roles.
  if (/\bproduct manager\b/.test(t) && !/\b(senior|staff|principal|group|director|head|vp)\b/.test(t)) return false;
  // "AI Solutions Engineer" is relevant; unrelated software / cloud engineering is not.
  if (/\bai solutions? engineer\b/.test(t)) return false;
  const blockedPatterns = [
    /\bsenior\s+manager\b/, /\bmanager\b/, /\bdirector\b/, /\bvp\b/,
    /\bvice\s+president\b/, /\bhead\b/, /\bteam\s+lead\b/, /\blead\b/,
    /\bsoftware engineer\b/, /\bdata engineer\b/, /\bdevops\b/,
    /\bcloud engineer\b/, /\bbackend engineer\b/, /\bfrontend engineer\b/,
    /\bfull[- ]?stack\b/, /\bplatform engineer\b/, /\bdeveloper\b/,
    /\bprogrammer\b/, /\btechnical\s+architect\b/,
    /\baccountant\b/, /\baccounting\b/, /\bbookkeeper\b/,
    /\bcontroller\b/, /\bpayroll\b/, /\baccounts\s+payable\b/,
    /\baccounts\s+receivable\b/, /\btax\b/, /\baudit\b/,
    /\bsales\b/, /\baccount\s+executive\b/, /\badministrative\b/,
    /\bassistant\b/, /\bco-?op\b/, /\bcoop\b/, /\bstudent\b/,
    /\bvolunteer\b/, /\bcase\s+review\b/, /\baml\s+investigator\b/,
    /\bcompliance\s+testing\b/
  ];
  return blockedPatterns.some((pattern) => pattern.test(t));
}

function getTier(j) {
  const title = getTitle(j);
  const score = getScore(j);
  const decision = getDecision(j);

  if (isBlockedTitle(title) || j._technical_screening === 'core_coding_title' || j._technical_screening === 'advanced_coding_primary') {
    return 99;
  }

  if (decision === "Priority Apply" && score >= 75) {
    return 1;
  }

  if (decision === "Apply" && score >= 70) {
    return 2;
  }

  if (decision === "Borderline" && score >= 65) {
    return 3;
  }

  return 99;
}

function matchesTargetFamily(family) {
  const f = String(family || "").trim().toLowerCase();
  return ["ai solutions product", "business strategy analytics", "global markets risk"].includes(f);
}

const HIGH_VALUE_TERMS = [
  "ai product", "ai solutions", "ai solution", "ai implementation", "ai automation",
  "ai transformation", "ai business transformation", "ai workflow", "ai strategy", "ai process automation",
  "technical product", "data product",
  "business insights", "business performance", "business strategy", "strategy analyst",
  "strategy analytics", "business analyst", "customer insights", "customer analytics",
  "product analyst", "product analytics", "growth analytics", "business operations",
  "process improvement", "process optimization", "operational excellence",
  "global markets", "capital markets", "market risk", "risk strategy",
  "credit risk", "credit strategy", "counterparty credit risk", "fraud risk",
  "fraud strategy", "payment risk", "transaction risk", "treasury", "alm",
  "interest rate risk", "fx risk", "foreign exchange", "rates analyst", "fixed income"
];

function matchesHighValueDirection(title, keywordsText) {
  const text = (String(title || "") + " " + String(keywordsText || "")).toLowerCase();
  for (const term of HIGH_VALUE_TERMS) {
    if (text.includes(term)) return true;
  }
  return false;
}

function isProtectedMatch(j) {
  const score = getScore(j);
  const decision = getDecision(j);
  const seniority = getSeniority(j).toLowerCase();
  const title = getTitle(j);

  if (isBlockedTitle(title) || j._technical_screening === 'core_coding_title' || j._technical_screening === 'advanced_coding_primary') return false;
  if (score < 75) return false;
  if (decision !== "Priority Apply" && decision !== "Apply") return false;
  if (!isToronto(j)) return false;
  if (seniority !== "good" && seniority !== "stretch") return false;
  if (!matchesTargetFamily(getTargetFamily(j))) return false;
  if (!matchesHighValueDirection(title, getKeywordsText(j))) return false;

  return true;
}

function enrichItem(item) {
  const j = item.json || {};
  const tier = getTier(j);
  return {
    json: {
      ...j,
      _top5_tier: tier,
      _top5_score: getScore(j),
      _top5_decision: getDecision(j),
      _top5_title: getTitle(j),
      _top5_company: getCompany(j),
      _top5_location: getLocation(j),
      _top5_is_toronto: isToronto(j),
      _top5_blocked_title: isBlockedTitle(getTitle(j)),
      _top5_protected: isProtectedMatch(j)
    },
    pairedItem: item.pairedItem,
  };
}

function compareItems(a, b) {
  if (a.json._top5_tier !== b.json._top5_tier) {
    return a.json._top5_tier - b.json._top5_tier;
  }

  if (b.json._top5_score !== a.json._top5_score) {
    return b.json._top5_score - a.json._top5_score;
  }

  if (a.json._top5_is_toronto !== b.json._top5_is_toronto) {
    return a.json._top5_is_toronto ? -1 : 1;
  }

  return 0;
}

const enriched = itemsIn.map(enrichItem);

const ranked = enriched
  .filter((item) => item.json._top5_tier < 99)
  .sort(compareItems);

const highScoreJobs = ranked.filter((item) => item.json._top5_score >= 80);

let selected;
let outputMode;
if (highScoreJobs.length > 5) {
  selected = highScoreJobs.slice();
  outputMode = "all_80_plus";
} else {
  selected = ranked.slice(0, 5);
  outputMode = "top5";
}

const protectedMatches = enriched.filter((item) => item.json._top5_protected);

const seen = new Set();
const merged = [];

for (const item of selected) {
  const key = jobKey(item.json);
  if (seen.has(key)) continue;
  seen.add(key);
  merged.push(item);
}

for (const item of protectedMatches) {
  const key = jobKey(item.json);
  if (seen.has(key)) continue;
  seen.add(key);
  merged.push(item);
}

merged.sort(compareItems);

const output = merged.slice(0, MAX_OUTPUT);
const protectedInOutput = output.filter((item) => item.json._top5_protected).length;

for (let i = 0; i < output.length; i++) {
  output[i].json._top5_output_mode = outputMode;
  output[i].json._top5_output_count = output.length;
  output[i].json._top5_high_score_count = highScoreJobs.length;
  output[i].json._top5_protected_count = protectedInOutput;
  output[i].json._top5_max_output = MAX_OUTPUT;
}

return output;

