function isAdvancedCodingPrimary(title, desc) {
  // Conservative JD-only override: require both core development ownership AND a specialized hard prerequisite.
  // Cross-functional work with engineers or using ordinary SQL, Python and APIs is not enough.
  if (isEngineeringHeavy(title, desc)) return true;
  const coreOwnership = /\b(?:responsible for|you will|you'll|design(?:ing)? and|build(?:ing)? and|develop(?:ing)? and|own(?:ing)? the)\b.{0,125}\b(?:train(?:ing)?|fine[- ]?tun(?:e|ing)|develop(?:ing)?|build(?:ing)?|architect(?:ing)?|deploy(?:ing)?|maintain(?:ing)?)\b.{0,90}\b(?:ml models?|deep learning|neural networks?|distributed systems|production[- ]grade software|backend services|model serving|ml pipelines?)\b/i.test(desc);
