  return coreOwnership && hardPrereq;
}

function hasSeniorProductExperienceGap(title, desc) {
  if (!/\b(?:ai |technical )?product manager\b/i.test(title)) return false;
  const directProductYears = /\b(?:[5-9]|1[0-9])\s*\+?\s*(?:years?|yrs?)\s+(?:of\s+)?(?:direct\s+|hands[- ]on\s+|professional\s+)?(?:product management|product manager|product ownership|pm experience)\b/i;
