  return directProductYears.test(desc) || minYears.test(desc);
}

function isComplianceOpsHeavy(title, desc) {
  // Do not remove data/risk/AI jobs merely because the JD mentions AML or compliance reviews.
  return COMPLIANCE_OPS_RE.some(re => re.test(title));
