}

function isLocationBad(loc, desc) {
  if (!loc && !desc) return false;
  const hay = (loc + ' ' + desc).toLowerCase();
  if (CANADA_OK.test(hay)) return false;
  if (/\b(remote|work from home|wfh)\b/i.test(hay) && /\bcanada\b/i.test(hay)) return false;
  if (/\b(united states|usa|u\.s\.|new york|california|texas|florida|seattle|boston|chicago)\b/i.test(hay) && !/\bcanada\b/i.test(hay)) return true;
  if (/\b(relocation required|must relocate|relocate to)\b/i.test(hay) && !CANADA_OK.test(hay)) return true;
  if (loc && !/\bcanada\b/i.test(loc) && !CANADA_OK.test(loc)) return true;
  return false;
}


function requiresCurrentEnrollment(title, desc) {
  const hay = (title + ' ' + desc).toLowerCase();
  if (/\bco[- ]?op enrollment\b/i.test(hay)) return true;
  if (/\bcurrent(ly)? enrolled\b/i.test(hay) && /\b(undergrad|student|co[- ]?op)\b/i.test(hay)) return true;
  if (/\b(must be|currently)\s+(a\s+)?student\b/i.test(hay)) return true;
  if (/\b(current student|actively enrolled|enrolled in (a )?(university|college|degree) program)\b/i.test(hay)) return true;
  if (/\b(campus program|graduate program|rotational program)\b/i.test(hay) && /\b(current(ly)? enrolled|must be enrolled|active student|co[- ]?op enrollment)\b/i.test(hay)) return true;
  return false;
}

function priorityBucket(title) {
  const p1 = [
    // Three target families, equal priority
    /ai product/i, /technical product analyst/i, /data product analyst/i, /ai solutions?/i,
    /ai implementation/i, /ai automation/i, /ai business transformation/i,
    /ai transformation/i, /ai business analyst/i, /ai workflow automation/i, /applied ai/i,
    /business analyst/i, /business insights/i, /business performance/i, /business strategy/i,
    /strategy analyst/i, /strategy analytics/i, /customer insights/i, /customer analytics/i,
    /product analyst/i, /product analytics/i, /growth analytics/i, /business operations analyst/i,
    /process improvement analyst/i, /process optimization analyst/i, /operational excellence analyst/i,
    /global markets/i, /capital markets/i, /market risk/i, /risk strategy/i,
    /credit risk/i, /credit strategy/i, /counterparty credit risk/i, /fraud risk/i,
    /fraud strategy/i, /payment risk/i, /transaction risk/i, /treasury analyst/i,
    /alm analyst/i, /fx risk/i, /rates analyst/i, /fixed income analyst/i,
    /interest rate risk/i, /risk analyst/i,
  ];
  const p2 = [/data analyst/i, /growth analyst/i, /operations analyst/i, /performance analyst/i,
              /financial analyst/i, /fp&a analyst/i, /portfolio analyst/i, /process analyst/i];
  if (p1.some(re => re.test(title))) return 1;
  if (p2.some(re => re.test(title))) return 2;
  return 3;
}

function computeDecision(overall, seniority, family, flags) {
  if (flags.block) return 'Not Recommended';
  if (overall < 55 || family === 'Not Fit' || seniority === 'Not Fit' || seniority === 'Too Junior') return 'Not Recommended';
  if (flags.managementHeavy || flags.accountingHeavy) return overall >= 55 ? 'Borderline' : 'Not Recommended';
  if (overall >= 80 && seniority === 'Good' && family !== 'Not Fit') return 'Priority Apply';
  if (overall >= 70 && (seniority === 'Good' || seniority === 'Stretch') && !flags.managementHeavy) return 'Apply';
  if (overall >= 55) return 'Borderline';
  return 'Not Recommended';
}

const j = { ...$json };
const title = getTitle(j);
const desc = getDesc(j);
const loc = getLocation(j);
const f = getFields(j);

const flags = {
  hardBan: TITLE_HARD.some(re => re.test(title)) || requiresCurrentEnrollment(title, desc) || (/\bsales\b/i.test(title) && !/analyst/i.test(title)),
  accountingHeavy: isAccountingHeavy(title),
  engineeringHeavy: isEngineeringHeavy(title, desc),
  advancedCodingPrimary: isAdvancedCodingPrimary(title, desc),
  seniorProductExperienceGap: hasSeniorProductExperienceGap(title, desc),
  complianceOps: isComplianceOpsHeavy(title, desc),
  managementHeavy: isManagementHeavy(title, desc),
  locationBad: isLocationBad(loc, desc),
  campaign: CAMPAIGN_RE.test(title) || CAMPAIGN_RE.test(desc),
  biDevOnly: BI_DEV_RE.test(title) && !ANALYTICS_JD.test(desc),
};

flags.block = flags.hardBan || flags.accountingHeavy || flags.engineeringHeavy || flags.advancedCodingPrimary || flags.complianceOps || flags.locationBad;
j._technical_screening = flags.engineeringHeavy ? 'core_coding_title' : (flags.advancedCodingPrimary ? 'advanced_coding_primary' : (flags.seniorProductExperienceGap ? 'direct_product_management_experience_gap' : 'passed'));

if (flags.accountingHeavy) {
  f.overall = Math.min(f.overall, 45);
  f.decision = 'Not Recommended';
  f.seniority = 'Not Fit';
  f.family = 'Not Fit';
} else if (flags.block) {
  f.overall = Math.min(f.overall, 40);
  f.decision = 'Not Recommended';
  if (flags.hardBan && /\bco[- ]?op|student\b/i.test(title)) f.seniority = 'Too Junior';
  else if (flags.engineeringHeavy || flags.advancedCodingPrimary) { f.seniority = 'Not Fit'; f.family = 'Not Fit'; }
  else f.seniority = f.seniority || 'Not Fit';
} else {
  if (flags.seniorProductExperienceGap) {
    f.overall = Math.min(f.overall, 54);
    f.seniority = 'Too Senior';
  }
  if (flags.managementHeavy) {
    f.overall = Math.min(f.overall, 60);
    if (f.seniority === 'Good') f.seniority = 'Too Senior';
    if (f.seniority !== 'Stretch') f.seniority = 'Too Senior';
  }

  if (flags.campaign) {
    const strong = FIN_SERV_JD.test(desc) && ANALYTICS_JD.test(desc);
    if (!strong) f.overall = Math.min(f.overall, 60);
  }

  if (flags.biDevOnly) {
    f.overall = Math.min(f.overall, 65);
  }

  if (flags.locationBad) {
    f.overall = Math.min(f.overall, 45);
    f.decision = 'Not Recommended';
  } else if (!CANADA_OK.test(loc) && loc) {
    f.overall = Math.min(f.overall, f.overall);
    if (f.score && f.score.location_work_arrangement_fit != null) {
      f.score.location_work_arrangement_fit = Math.min(Number(f.score.location_work_arrangement_fit), 2);
    }
  }

  f.decision = flags.seniorProductExperienceGap ? 'Not Recommended' : computeDecision(f.overall, f.seniority, f.family, flags);
  if (flags.managementHeavy && (f.decision === 'Apply' || f.decision === 'Priority Apply')) f.decision = 'Borderline';
  if (flags.campaign && f.overall <= 60 && f.decision === 'Apply') f.decision = 'Borderline';
}

// Keep score components consistent when deterministic guardrails reduce the overall score.
if (f.score && typeof f.score === 'object') {
  const fields = [
    ['target_role_fit',25], ['business_scenario_fit',20],
    ['technical_analytical_skill_fit',20], ['experience_evidence_fit',15],
    ['seniority_feasibility_fit',15], ['location_work_arrangement_fit',5],
  ];
  if (fields.every(([key]) => Number.isFinite(Number(f.score[key])))) {
    for (const [key,max] of fields) f.score[key] = Math.max(0,Math.min(max,Number(f.score[key])));
    if (flags.engineeringHeavy || flags.advancedCodingPrimary) {
      f.score.technical_analytical_skill_fit = Math.min(f.score.technical_analytical_skill_fit,4);
      f.score.target_role_fit = Math.min(f.score.target_role_fit,5);
      f.score.experience_evidence_fit = Math.min(f.score.experience_evidence_fit,5);
    }
    if (flags.seniorProductExperienceGap) {
      f.score.seniority_feasibility_fit = Math.min(f.score.seniority_feasibility_fit,4);
    }
    let sum = fields.reduce((total,[key])=>total+f.score[key],0);
    // Reduce least-relevant sub-scores until the original cap is respected.
    const reductionOrder = ['target_role_fit','technical_analytical_skill_fit','experience_evidence_fit','seniority_feasibility_fit','business_scenario_fit','location_work_arrangement_fit'];
    for (const key of reductionOrder) {
      if (sum <= f.overall) break;
      const loss = Math.min(f.score[key],sum-f.overall);
      f.score[key] -= loss;
      sum -= loss;
    }
    // Avoid an overall greater than the sum of components after hard constraints.
    f.overall = Math.min(f.overall,sum);
  }
}

f.priorityBucket = priorityBucket(title);
return { json: setFields(j, f), pairedItem: $input.item?.pairedItem ?? { item: $itemIndex } };
